export function hhTrace(steps=24){if(!Number.isInteger(steps)||steps<0||steps>100)throw new RangeError('steps 0..100');let empty=1,h=0,done=0,truncated=0;const frames=[];for(let n=0;n<=steps;n++){frames.push({n,empty,h,done,survival:empty+h,truncated});truncated+=empty+h;const nextEmpty=(empty+h)/2,nextH=empty/2;done+=h/2;empty=nextEmpty;h=nextH;}return frames;}
export function arrivals(rate,minutes,k=1){if(!Number.isFinite(rate)||rate<0||rate>12||!Number.isFinite(minutes)||minutes<0||minutes>60||!Number.isInteger(k)||k<1||k>4)throw new RangeError('Lab domain exceeded');const mean=rate*minutes/60,mass=[Math.exp(-mean)];for(let i=1;i<=8;i++)mass.push(mass[i-1]*mean/i);const tail=Math.max(0,1-mass.reduce((a,b)=>a+b,0)),cdf=Math.max(0,1-mass.slice(0,k).reduce((a,b)=>a+b,0));return {rate,minutes,k,mean,mass,tail,cdf,expectedMinutes:rate?k*60/rate:Infinity};}
export function questionBound(worlds,branches){if(!Number.isSafeInteger(worlds)||worlds<1||!Number.isSafeInteger(branches)||branches<2)throw new RangeError('Positive worlds; at least two outcomes');let capacity=1n,depth=0;while(capacity<BigInt(worlds)){capacity*=BigInt(branches);depth++;}return {depth,capacity};}
